  public function executeMarcar()
  {
  	$marcar = 0;
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	$solicitud_prestamo = SolicitudPrestamoPeer::retrieveByPK($this->getRequestParameter('solicitudprestamo_id'));
  	if($solicitud_prestamo->getMarca() == 0 || $solicitud_prestamo->getMarca() != $usuariologuiado)
  	{
  		$marcar = $usuariologuiado;
  	}
  	$solicitud_prestamo->setMarca($marcar);
  	$solicitud_prestamo->save();
  }
  
  public function executeRechazar()
  {
  	/**************************************************************************************************************/
  	$solicitud_prestamo = SolicitudPrestamoPeer::retrieveByPk($this->getRequestParameter('solicitudprestamo_id'));
  	$solicitud_prestamo->setSolicitudprestamoestadoId(3);
  	$solicitud_prestamo->setFechaAtencion(date("Y-m-d G:i:s"));
  	$solicitud_prestamo->save();
  	/**************************************************************************************************************/
  }
  
  public function executeRechazarMarcados()
  {
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	$c = new Criteria();
  	$c->add(SolicitudPrestamoPeer::MARCA,$usuariologuiado);
  	$c->add(SolicitudPrestamoPeer::SOLICITUDPRESTAMOESTADO_ID,1);
  	$all_solicitudes = SolicitudPrestamoPeer::doSelect($c);
  	foreach ($all_solicitudes as $solicitud_prestamo ) {
  		$solicitud_prestamo->setSolicitudprestamoestadoId(3);
  		$solicitud_prestamo->setFechaAtencion(date("Y-m-d G:i:s"));
  		$solicitud_prestamo->save();
  	}
  }
  
