  public function executeAdicionar()
  {
  	/**************************************************************************************************************/  	 
  	$solicitud_prestamo = SolicitudPrestamoPeer::retrieveByPk($this->getRequestParameter('solicitudprestamo_id'));		
	/**************************************************************************************************************/
		
	/**************************************************************************************************************/	
	$this->getUser()->addCredential('prestamo');
	$cadSolicitud   = $this->getUser()->getAttribute('solicitud','','prestamo');
	if($cadSolicitud == ''){
		$cadSolicitud  .=  $solicitud_prestamo->getSolicitudprestamoId();		
		$this->getUser()->setAttribute('solicitud', $cadSolicitud, 'prestamo');	
	}else{
		$cadSolicitud  .=  ','.$solicitud_prestamo->getSolicitudprestamoId();		
		$this->getUser()->setAttribute('solicitud', $cadSolicitud, 'prestamo');
	}
	/**************************************************************************************************************/  
  }  
  
