  public function getNumRadicacion($regional)
  {
    $periodoActual = date("Y");
    $parametro = ParametroPeer::retrieveByPk(34);
    $formaRad = $parametro->getCodigo();
    $conexion = Propel::getConnection();
    //************************************************************************************
    if ($formaRad == "REG") {
        $consulta = "SELECT MAX(%s) AS max FROM %s where %s=" . $regional . "  and %s=" .$periodoActual . " ";
        $consulta = sprintf($consulta, PrestamoPeer::NUMERO_RADICACION, PrestamoPeer::TABLE_NAME, PrestamoPeer::REGIONAL_ID, PrestamoPeer::PERIODO_ID);
    }elseif ($formaRad == "GEN") {
        $consulta = "SELECT MAX(%s) AS max FROM %s where  %s=" . $periodoActual . " ";
        $consulta = sprintf($consulta, PrestamoPeer::NUMERO_RADICACION, PrestamoPeer::TABLE_NAME, PrestamoPeer::PERIODO_ID);
    }
    //************************************************************************************
    $sentencia = $conexion->prepare($consulta);
    $sentencia->execute();
    $resultset = $sentencia->fetch(PDO::FETCH_OBJ);
    return ($resultset->max + 1);
    //************************************************************************************
  }
  
