    public function getFechaVence()
	{
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$usuario  = UsuarioPeer::retrieveByPK($usuariologuiado);
		$dias_prestamo  = $usuario->getDependencia()->getTiempoPrestamo();
		$vence   = AddDays(date("Y-m-d"),$dias_prestamo);
		return $vence;
	}
	
	public function uniquename($opendir,$prefix = "plantilla_",$suffix = ".php") 
    {
		$dir_handle = @opendir($opendir) or die("Unable to open $path");

		$max = 0;
		while ($file = readdir($dir_handle)) {
			preg_match("/^$prefix?(.*?)$suffix$/", $file, $treffer);
			$id = $treffer[1];
			if ( $id != "" && $id > $max ) {
				$max = $id;
			}		
		}
		closedir($dir_handle);

		return $prefix . ($max + 1) . $suffix;
	}
}
